import{_ as i,c as e,o as s,ag as t}from"./chunks/framework.C7v41-tM.js";const c=JSON.parse('{"title":"Skill 盘点：文件数为何不等于可用技能数","description":"","frontmatter":{},"headers":[],"relativePath":"notes/skill-inventory.md","filePath":"notes/skill-inventory.md","lastUpdated":null}'),l={name:"notes/skill-inventory.md"};function n(r,a,h,o,p,d){return s(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="skill-盘点-文件数为何不等于可用技能数" tabindex="-1">Skill 盘点：文件数为何不等于可用技能数 <a class="header-anchor" href="#skill-盘点-文件数为何不等于可用技能数" aria-label="Permalink to &quot;Skill 盘点：文件数为何不等于可用技能数&quot;">​</a></h1><p>先问清楚要统计磁盘文件、插件登记，还是当前会话可用能力。基本定义见 <a href="https://github.com/lixudong1649/jdp-wiki/blob/main/content/terms/agent-skill.md" target="_blank" rel="noreferrer">Agent Skill</a>。</p><h2 id="三个容易误判的地方" tabindex="-1">三个容易误判的地方 <a class="header-anchor" href="#三个容易误判的地方" aria-label="Permalink to &quot;三个容易误判的地方&quot;">​</a></h2><ul><li>同一技能可能同时存在于共享目录、软链接与插件缓存，不能简单相加。</li><li>同一插件可能留有多个版本，旧缓存不是当前启用证据。</li><li>示例、模板与只读上游目录可能含 SKILL.md，不等于宿主会加载它们。</li></ul><h2 id="从小范围开始" tabindex="-1">从小范围开始 <a class="header-anchor" href="#从小范围开始" aria-label="Permalink to &quot;从小范围开始&quot;">​</a></h2><p>先检查用户明确选定的目录和当前项目，再查已知插件层级。保留目录状态、技能名、真实路径和来源；缺目录、权限不足与无匹配分别记录。</p><p>可用下面的命令观察一个明确授权目录中的技能文件。<code>&lt;approved-directory&gt;</code> 为占位，需要替换；该命令只列文件，不执行技能。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rg</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --files</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --hidden</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">approved-director</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">y</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> SKILL.md</span></span></code></pre></div><p>这不是完整的宿主安装扫描器，忽略规则、软链接和自定义目录会影响结果。需要深入盘点时按固定插件层级解析，不无边界递归整个磁盘。</p><h2 id="对照宿主-而不是替宿主下结论" tabindex="-1">对照宿主，而不是替宿主下结论 <a class="header-anchor" href="#对照宿主-而不是替宿主下结论" aria-label="Permalink to &quot;对照宿主，而不是替宿主下结论&quot;">​</a></h2><p>再核对插件登记、启用设置和当前会话清单；代表任务成功只证明特定环境下能执行。输出先给分组数量，再按需展开必要明细，避免数百条路径把结果截断。</p><p>盘点输出可能暴露用户名、插件名和项目路径，留在本机临时目录；公开文章只保留方法，不上传真实盘点清单。</p><p>参考：<a href="https://agentskills.io/specification" target="_blank" rel="noreferrer">Agent Skills 规范</a>。本文是盘点经验整理，不保证每个宿主采用同一目录布局；整理：2026-10-14。</p>',13)])])}const g=i(l,[["render",n]]);export{c as __pageData,g as default};
